cypress_script:
describe('Frames Page Navigation', () => {
  it('should navigate to Nested Frames', () => {
    cy.visit('https://the-internet.herokuapp.com/frames');
    cy.get('a').contains('Nested Frames').click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/nested_frames');
  });
  it('should not navigate to an invalid link', () => {
    cy.visit('https://the-internet.herokuapp.com/frames');
    cy.get('a').contains('iFrame').click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/iframe');
    cy.get('#flash-messages').should('not.exist');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Frames Page Navigation', () => {
  test('should navigate to Nested Frames', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/frames');
    await page.click('text=Nesting Frames');
    expect(page.url()).toBe('https://the-internet.herokuapp.com/nested_frames');
  });
  test('should not navigate to an invalid link', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/frames');
    await page.click('text=iFrame');
    expect(page.url()).toBe('https://the-internet.herokuapp.com/iframe');
    const flashMessages = page.locator('#flash-messages');
    expect(await flashMessages.count()).toBe(0);
  });
});
